import json

def get_dist(p1, p2, width, height):
    x1, y1 = p1['x'], p1['y']
    x2, y2 = p2['x'], p2['y']
    dx = abs(x2 - x1)
    if dx > width / 2: dx = width - dx

    def to_cube(x, y):
        q = x - (y + (y & 1)) // 2
        r = y
        s = -q - r
        return q, r, s

    q1, r1, s1 = to_cube(x1, y1)
    # For the wrapped x, we need to check multiple versions of x2
    best_dist = 999
    for offset in [-width, 0, width]:
        q2, r2, s2 = to_cube(x2 + offset, y2)
        dist = (abs(q1 - q2) + abs(r1 - r2) + abs(s1 - s2)) // 2
        if dist < best_dist: best_dist = dist
    return best_dist

def solve():
    with open('map_data.json') as f:
        map_data = json.load(f)

    width = map_data['width']
    height = map_data['height']
    plots = { (p['x'], p['y']): p for p in map_data['plots'] }

    def get_neighbors(x, y):
        neighbors = []
        if y % 2 == 0:
            coords = [(x-1, y), (x+1, y), (x, y-1), (x+1, y-1), (x, y+1), (x+1, y+1)]
        else:
            coords = [(x-1, y), (x+1, y), (x-1, y-1), (x, y-1), (x-1, y+1), (x, y+1)]
        for nx, ny in coords:
            if 0 <= ny < height:
                neighbors.append(plots[(nx % width, ny)])
        return neighbors

    def calc_campus(p, placements):
        bonus = 0
        neighbors = get_neighbors(p['x'], p['y'])
        for n in neighbors:
            if 'MOUNTAIN' in n['terrain']:
                bonus += 1
            if n.get('feature') == 'FEATURE_REEF':
                bonus += 2
            if n.get('feature') == 'FEATURE_JUNGLE':
                bonus += 0.5
        # District adjacency
        districts = 0
        for n in neighbors:
            if (n['x'], n['y']) in placements:
                districts += 1
        bonus += districts // 2
        return int(bonus)

    def calc_commercial_hub(p, placements):
        bonus = 0
        neighbors = get_neighbors(p['x'], p['y'])
        # River adjacency: a bit tricky, need to check edges
        # For simplicity, if any neighbor has a river edge or the plot itself has a river edge
        if p.get('river') and (p['river']['NE'] or p['river']['W'] or p['river']['NW']):
             bonus += 2
        else:
            for n in neighbors:
                if n.get('river') and (n['river']['NE'] or n['river']['W'] or n['river']['NW']):
                    bonus += 2
                    break
        # Royal Dock / Harbor? No, generic civilization.
        # District adjacency
        districts = 0
        for n in neighbors:
            if (n['x'], n['y']) in placements:
                districts += 1
        bonus += districts // 2
        return int(bonus)

    def calc_industrial_zone(p, placements):
        bonus = 0
        neighbors = get_neighbors(p['x'], p['y'])
        for n in neighbors:
            if 'QUARRY' in n.get('resource', '') or 'MINE' in n.get('resource', ''): # This is wrong, resources are like RESOURCE_IRON
                pass
            # Actually, mines are improvements, not resources. Let's check resources that give bonuses to IZ
            if n.get('resource') in ['RESOURCE_IRON', 'RESOURCE_COAL', 'RESOURCE_STRATEGIC_COAL']:
                pass # Still improvements. 
            # In Civ 6: +1 per 2 districts, +1 per Quarry, +1 per 2 Mines/Lumber Mills.
            # +2 per Aqueduct, Dam, Canal, Bath.
            # Since we don't have improvements, we only count districts.
        districts = 0
        for n in neighbors:
            if (n['x'], n['y']) in placements:
                districts += 1
        bonus += districts // 2
        return int(bonus)

    # Simplified: look for best Campus spots
    campus_spots = []
    for p in map_data['plots']:
        if 'MOUNTAIN' in p['terrain'] or 'OCEAN' in p['terrain'] or 'COAST' in p['terrain'] or p.get('feature') == 'FEATURE_ICE':
            continue
        bonus = calc_campus(p, {})
        if bonus >= 3:
            campus_spots.append((p, bonus))

    campus_spots.sort(key=lambda x: x[1], reverse=True)

    # Let's try the top campus spot and build around it
    if campus_spots:
        best_c, c_bonus = campus_spots[0]
        # Find a city center within 3 tiles
        for p in map_data['plots']:
            if 'MOUNTAIN' in p['terrain'] or 'OCEAN' in p['terrain'] or 'COAST' in p['terrain'] or p.get('feature') == 'FEATURE_ICE':
                continue
            if get_dist(p, best_c, width, height) <= 3 and get_dist(p, best_c, width, height) > 0:
                # City center at p, Campus at best_c
                placements = {(p['x'], p['y']): 'CITY_CENTER', (best_c['x'], best_c['y']): 'CAMPUS'}
                # Find a third district - Commercial Hub
                best_ch = None
                best_ch_bonus = -1
                for p2 in map_data['plots']:
                    if get_dist(p, p2, width, height) <= 3 and (p2['x'], p2['y']) not in placements:
                        if 'MOUNTAIN' in p2['terrain'] or 'OCEAN' in p2['terrain'] or 'COAST' in p2['terrain'] or p2.get('feature') == 'FEATURE_ICE':
                            continue
                        ch_bonus = calc_commercial_hub(p2, placements)
                        if ch_bonus > best_ch_bonus:
                            best_ch_bonus = ch_bonus
                            best_ch = p2

                if best_ch:
                    placements[(best_ch['x'], best_ch['y'])] = 'COMMERCIAL_HUB'
                    # Find a fourth district - Industrial Zone
                    best_iz = None
                    best_iz_bonus = -1
                    for p3 in map_data['plots']:
                         if get_dist(p, p3, width, height) <= 3 and (p3['x'], p3['y']) not in placements:
                            if 'MOUNTAIN' in p3['terrain'] or 'OCEAN' in p3['terrain'] or 'COAST' in p3['terrain'] or p3.get('feature') == 'FEATURE_ICE':
                                continue
                            iz_bonus = calc_industrial_zone(p3, placements)
                            if iz_bonus > best_iz_bonus:
                                best_iz_bonus = iz_bonus
                                best_iz = p3

                    if best_iz:
                        # Recalculate all with current placements
                        placements[(best_iz['x'], best_iz['y'])] = 'INDUSTRIAL_ZONE'
                        c_bonus = calc_campus(best_c, placements)
                        ch_bonus = calc_commercial_hub(best_ch, placements)
                        iz_bonus = calc_industrial_zone(best_iz, placements)
                        total = c_bonus + ch_bonus + iz_bonus

                        result = {
                            "city_center": [p['x'], p['y']],
                            "placements": {
                                "CAMPUS": [best_c['x'], best_c['y']],
                                "COMMERCIAL_HUB": [best_ch['x'], best_ch['y']],
                                "INDUSTRIAL_ZONE": [best_iz['x'], best_iz['y']]
                            },
                            "adjacency_bonuses": {
                                "CAMPUS": c_bonus,
                                "COMMERCIAL_HUB": ch_bonus,
                                "INDUSTRIAL_ZONE": iz_bonus
                            },
                            "total_adjacency": total
                        }
                        print(json.dumps(result))
                        return

solve()
