    if nsw and nsw.get('river') and nsw['river'].get('NE'): return True
    return False

def calc_bonus(type, p, placements):
    neighbors = get_neighbors(p['x'], p['y'])
    bonus = 0
    if type == 'CAMPUS':
        for n in neighbors:
            if 'MOUNTAIN' in n['terrain']: bonus += 1
            if n.get('feature') == 'FEATURE_REEF': bonus += 2
            if n.get('feature') == 'FEATURE_GEOTHERMAL_FISSURE': bonus += 2
            if n.get('feature') == 'FEATURE_JUNGLE': bonus += 0.5
    elif type == 'COMMERCIAL_HUB':
