    elif type == 'HOLY_SITE':
        for n in neighbors:
            if 'MOUNTAIN' in n['terrain']: bonus += 1
            if n.get('feature') == 'FEATURE_FOREST': bonus += 0.5
    elif type == 'INDUSTRIAL_ZONE':
        pass

    districts = sum(1 for n in neighbors if (n['x'], n['y']) in placements)
    bonus += districts // 2
    return int(bonus)

